function EditModal({task,store,onClose,onSave,onChangeRecurrence,onStopRecurrence}:{task:Task;store:Store;onClose:()=>void;onSave:(t:Task,title:string,steps:Step[],scope:'task'|'future',time:string|null,dueDate:string,deadline:string|null,priority:Priority,durationMin:number|null,reminderMin:number|null)=>void;onChangeRecurrence:(t:Task,title:string,schedule:Schedule,scope:'occurrence'|'future'|'series',time:string|null)=>void;onStopRecurrence:(t:Task)=>void}){const plan=task.planId?store.plans.find(p=>p.id===task.planId):null;const initialSchedule=plan?.schedule??plan?.stoppedSchedule??{type:'daily'};const[title,setTitle]=useState(task.title),[steps,setSteps]=useState(stepsFor(store,task)),[time,setTime]=useState(task.dueTime),[dueDate,setDueDate]=useState(task.dueDate),[deadline,setDeadline]=useState<string|null>(task.deadline??null),[priority,setPriority]=useState<Priority>(task.priority??'normal'),[durationMin,setDurationMin]=useState<number|null>(task.durationMin??null),[schedule,setSchedule]=useState<Schedule>(initialSchedule),[reminderMin,setReminderMin]=useState<number|null>(task.reminderMin??null),[recScope,setRecScope]=useState<'occurrence'|'future'|'series'>('future'),[stopRecurrence,setStopRecurrence]=useState(!plan?.schedule);const weeklyDays=schedule?.type==='weekly'?schedule.days:[0,2,4];const setType=(type:string)=>setSchedule(type==='daily'?{type:'daily'}:type==='weekly'?{type:'weekly',days:weeklyDays}:{type:'monthly',dayOfMonth:15});const toggleRecurrence=(active:boolean)=>{setStopRecurrence(!active);if(active)setSchedule(plan?.stoppedSchedule??plan?.schedule??{type:'daily'})};return <Modal title="Edit task" onClose={onClose}><div className="space-y-5 p-5 sm:p-6"><input value={title} onChange={e=>setTitle(e.target.value)} className="w-full rounded-xl border border-gray-200 p-3 text-sm" placeholder="Task title"/><label className="block"><span className="mb-2 block text-xs font-semibold uppercase tracking-wider text-gray-400">Time (optional)</span><input type="time" value={time||''} onChange={e=>setTime(e.target.value||null)} className="rounded-xl border border-gray-200 p-3 text-sm"/></label><label className="block"><span className="mb-2 block text-xs font-semibold uppercase tracking-wider text-gray-400">Scheduled date</span><input type="date" min={dateKey()} value={dueDate} onChange={e=>setDueDate(e.target.value)} className="w-full rounded-xl border border-gray-200 p-3 text-sm"/><label className="mt-2 flex items-center gap-2 text-xs text-gray-500"><input type="checkbox" checked={!dueDate} onChange={e=>{if(e.target.checked)setDueDate('');else if(!dueDate)setDueDate(dateKey())}} /> No scheduled date · Open</label></label><label className="block"><span className="mb-2 block text-xs font-semibold uppercase tracking-wider text-gray-400">Deadline (optional)</span><input type="date" min={dateKey()} value={deadline||''} onChange={e=>setDeadline(e.target.value||null)} className="w-full rounded-xl border border-gray-200 p-3 text-sm"/></label><PriorityPicker value={priority} onChange={setPriority}/><ReminderPicker value={reminderMin} onChange={setReminderMin}/><DurationPicker value={durationMin} onChange={setDurationMin}/>{plan&&<div className="rounded-2xl border border-black/5 bg-gray-50 p-4"><div className="mb-3 flex items-center justify-between"><div><b className="text-sm">Recurrence</b><p className="text-xs text-gray-400">Current: {stopRecurrence?'Stopped':schedule?.type==='daily'?'Daily':schedule?.type==='weekly'?`Weekly · ${schedule.days.length} days`:`Monthly · day ${schedule?.dayOfMonth}`}</p></div><label className="relative inline-flex h-8 w-14 shrink-0 cursor-pointer items-center"><input type="checkbox" checked={!stopRecurrence} onChange={e=>toggleRecurrence(e.target.checked)} aria-label="Recurrence" className="peer sr-only"/><span className="absolute inset-0 rounded-full bg-gray-200 transition-colors peer-checked:bg-[#20221f] peer-focus-visible:ring-2 peer-focus-visible:ring-[#20221f] peer-focus-visible:ring-offset-2"/><span aria-hidden="true" className="absolute left-1 top-1 h-6 w-6 rounded-full bg-gray-400 shadow-sm transition-all duration-300 ease-out peer-checked:translate-x-6 peer-checked:bg-white"/></label></div><div className={stopRecurrence?'pointer-events-none opacity-40':''}><select disabled={stopRecurrence} value={schedule?.type||'daily'} onChange={e=>setType(e.target.value)} className="w-full rounded-xl border border-gray-200 bg-white p-3 text-sm"><option value="daily">Daily</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option></select>{schedule?.type==='weekly'&&<div className="mt-2 grid grid-cols-7 gap-1">{['M','T','W','T','F','S','S'].map((d,i)=><button key={i} type="button" disabled={stopRecurrence} onClick={()=>{const days=schedule.days.includes(i)?schedule.days.filter(x=>x!==i):[...schedule.days,i].sort();if(days.length)setSchedule({type:'weekly',days})}} className={`rounded-lg border p-2 text-xs ${schedule.days.includes(i)?'border-[#20221f] bg-[#20221f] text-white':'border-gray-200 bg-white text-gray-500'}`}>{d}</button>)}</div>}<div className="mt-3 grid gap-2 sm:grid-cols-3">{([['occurrence','This occurrence'],['future','This and future'],['series','Entire series']] as const).map(([id,label])=><button key={id} type="button" disabled={stopRecurrence} onClick={()=>setRecScope(id)} className={`rounded-xl border p-2 text-left text-xs ${recScope===id?'border-[#20221f] bg-white shadow-sm':'border-gray-200'}`}><b className="block">{label}</b><span className="text-gray-400">{id==='occurrence'?'Only this task':id==='future'?'From this task onward':'All pending occurrences'}</span></button>)}</div></div><button type="button" onClick={()=>stopRecurrence?onStopRecurrence(task):onChangeRecurrence(task,title.trim(),schedule,recScope,time)} disabled={!title.trim()||(!stopRecurrence&&!schedule)} className="mt-3 w-full rounded-xl bg-[#20221f] py-2.5 text-xs font-medium text-white disabled:opacity-40">{stopRecurrence?'Save stopped recurrence':plan.schedule?'Apply recurrence change':'Resume recurrence'}</button></div>}<StepEditor initial={steps} onChange={setSteps}/><div className="rounded-2xl bg-gray-50 p-4 text-sm text-gray-600">Choose the temporal scope. Stride never silently changes future behavior.</div><div className="grid gap-2 sm:grid-cols-2"><button disabled={!title.trim()} onClick={()=>onSave(task,title.trim(),steps.filter(s=>s.text.trim()),'task',time,dueDate,deadline,priority,durationMin,reminderMin)} className="rounded-xl border border-black/10 p-3 text-left disabled:opacity-40"><b className="block text-sm">Save for this task</b><span className="text-xs text-gray-400">Create a contextual experiment.</span></button><button disabled={!title.trim()||!task.planId} onClick={()=>onSave(task,title.trim(),steps.filter(s=>s.text.trim()),'future',time,dueDate,deadline,priority,durationMin,reminderMin)} className="rounded-xl bg-[#20221f] p-3 text-left text-white disabled:opacity-40"><b className="block text-sm">Save for future</b><span className="text-xs text-gray-300">Create a new master PlanVersion.</span></button></div>{!task.planId&&<p className="text-xs text-gray-400">One-off tasks can be customized or moved between scheduled and open states. Save as a reusable plan from the task actions.</p>}</div></Modal>}
function VersionModal({task,store,onClose,onChange}:{task:Task;store:Store;onClose:()=>void;onChange:(t:Task,id:string)=>void}){const vs=store.versions.filter(v=>v.planId===task.planId).sort((a,b)=>b.version-a.version),master=store.plans.find(p=>p.id===task.planId)?.currentVersionId;return <Modal title="Change execution version" onClose={onClose}><div className="p-5 sm:p-6"><p className="mb-4 text-sm text-gray-500">Choose which immutable version this execution uses.</p><div className="space-y-2">{vs.map(v=><button key={v.id} onClick={()=>onChange(task,v.id)} className={`flex w-full items-center justify-between rounded-xl border p-4 text-left ${v.id===task.planVersionId?'border-[#20221f] bg-gray-50':'border-gray-200 hover:bg-gray-50'}`}><span><b className="text-sm">v{v.version}</b><span className="ml-2 text-xs text-gray-400">{v.id===master?'Current master':''}</span></span><span className="text-xs text-gray-400">{v.steps.length} steps</span></button>)}</div></div></Modal>}
function TaskActionMenu({task,store,onClose,onEdit,onVersion,onSkip,onSaveAsPlan}:{task:Task;store:Store;onClose:()=>void;onEdit:()=>void;onVersion:()=>void;onSkip:()=>void;onSaveAsPlan:()=>void}){return <div className="fixed inset-0 z-50 flex items-end justify-center bg-black/25 p-3 sm:items-center" onMouseDown={onClose}><div className="w-full max-w-sm rounded-2xl bg-white p-2 shadow-2xl" onMouseDown={e=>e.stopPropagation()}><div className="flex items-center justify-between px-3 py-2"><div><p className="text-sm font-semibold">{task.title}</p><p className="text-xs text-gray-400">{task.planId?'Recurring task':'One-off task'}</p></div><button onClick={onClose}><X size={17}/></button></div><button onClick={onEdit} className="block w-full rounded-xl px-3 py-3 text-left text-sm hover:bg-gray-50">Edit task</button>{!task.planId&&<button onClick={onSaveAsPlan} className="block w-full rounded-xl px-3 py-3 text-left text-sm hover:bg-gray-50">Save as reusable plan</button>}{task.planId&&<button onClick={onVersion} className="block w-full rounded-xl px-3 py-3 text-left text-sm hover:bg-gray-50">Change version</button>}<button onClick={onSkip} className="block w-full rounded-xl px-3 py-3 text-left text-sm hover:bg-gray-50">{task.status==='skipped'?'Reopen task':'Skip task'}</button></div></div>}
